var result = base + "/005E.html";
try {
  var html = String(java.ajax(base + "/005E.html") || "");
  var mt = html.match(/name="_t" value="([a-f0-9]+)"/);
  var mv = html.match(/(?:src="[^"]*|action=)signJs&v=([^"']+)/) || html.match(/signJs[^"']*?v=([^"']+)/);
  if(mt && mv){
    var t = mt[1];
    var sj = "";
    try { sj = String(java.ajax(base + "/?action=signJs&v=" + mv[1]) || ""); } catch(e) {}
    var mq = sj.match(/var q=function[^{]*\{[\s\S]*?\};/);
    if(!mq){ mq = sj.match(/function\s+\w+\(s,t,ts\)\{[\s\S]*?\};/); }
    if(mq){
      try {
        var fn = mq[0].replace(/^var q=/, "").replace(/;$/, "");
        var qf = eval("(" + fn + ")");
        var enc = encURI(key);
        var ts = Math.floor(Date.now() / 1000);
        var sig = qf(enc, t, ts);
        var body = "keyword=" + encURI(key) + "&_t=" + t + "&_ts=" + ts + "&_s=" + sig;
        var postUrl = base + "/?action=search," + JSON.stringify({method: "POST", body: body});
        var first = "";
        try { first = String(java.ajax(postUrl) || ""); } catch(e) {}
        var qm = first.match(/action=find&v=(\d+)&q=([^&"']+?)&page=/);
        if(qm){
          result = base + "/?action=find&v=" + qm[1] + "&q=" + qm[2] + "&page={{page}}";
