original = {
	'rel': 'https://jmcomicne.net/',
	'urls': [
		'1', '2', '3'
	],
	'ci': 0,
	'shunt': 0,
	'tag1': 0,
	'tag2': 0,
	'ver': 2.2
};
GetInfo();
try {
	$$$ = JSON.parse(source.getVariable());
	if ($$$ == null) {
		error;
	} else {
		const tagKeyName = Object.keys($$$).find(key => key === 'ver');
		if (tagKeyName === undefined || $$$.ver !== 2.2) {
			error;
		}
	};
} catch (e) {
	$$$ = original;
	put($$$);
}

function login(e) {
	if (e == undefined) {
		return;
	}
	java.longToast(e);
}

function url() {
	login("启动")
	const baseUrl = java.connect(Get('rel')).url();
	$$$.rel = baseUrl;
	login('开始获取链接');
	const html = java.ajax(baseUrl);
	let allUrls = [];
	['china', 'first_line', 'second_line'].forEach(key => {
		const reg = new RegExp(`${key}\"><span>(.*?)<\\/span`);
		const match = html.match(reg);
		if (match && match[1]) {
			allUrls.push(match[1].replace(/\s+/g, ""));
		}
	});
	const uniqueUrls = [];
	allUrls.forEach(url => !uniqueUrls.includes(url) && url && uniqueUrls.push(url));
	$$$.urls = uniqueUrls
	java.log(JSON.stringify($$$.urls));
	login('获取成功' + n(2) + '到日志查看链接');
	return put($$$);
}

function n(e) {
	n = '\n';
	for (m = 1; m < e; m++) {
		n = n + '\n';
	}
	return n;
}

function typeSH(e) {
	if (e == undefined) {
		e = 0;
	}
	return SH[e];
}

function sh(e) {
	if (sh == undefined) {
		sh = result.sh;
	}
	if (e == $$$.shunt) {
		return;
	}
	login('【切换分流】' + n(2) + '已经切换到分流:[' + typeSH(e) + ']');
	$$$.shunt = e;
	return put($$$);
}

function qh(e) {
	if (Get('urls')[0] == 1) {
		login('请先获取URL');
	}
	if (qh == undefined) {
		qh = result.qh;
	}
	if (e == $$$.ci) {
		return;
	}
	login('【切换接口】' + n(2) + '已经切换到内地:[' + names[e] + ']');
	$$$.ci = e;
	return put($$$);
}

function qh1(e) {
	if (qh1 == undefined) {
		qh1 = result.qh1;
	}
	if (e == $$$.tag1) {
		return;
	}
	login('【切换排序】' + n(2) + '已经切换到排序:[' + sortNames[e] + ']');
	$$$.tag1 = e;
	return put($$$);
}

function qh2(e) {
	if (qh2 == undefined) {
		qh2 = result.qh2;
	}
	if (e == $$$.tag2) {
		return;
	}
	login('【切换分类】' + n(2) + '已经切换到分类:[' + categoryNames[e] + ']');
	$$$.tag2 = e;
	return put($$$);
}

function Login() {
	const result = JSON.parse(source.getLoginInfo());
	var username = result['账号'];
	var password = result['密码'];
	var options = {
		body: `username=${username}&password=${password}&submit_login=1`,
		method: 'POST'
	};
	if (Get('urls')[0] == 1) {
		login('请先获取URL');
	} else if (Get('urls')[Get('ci')]) {
		login("\n⏳正在登录中，请等一会，很快就好...");
		var request = JSON.parse(java.log(java.ajax(Get('urls')[Get('ci')] + `/login,${JSON.stringify(options)}`)))
		if (request.status == '1') {
			login('✅ 登录成功')
		} else {
			login('❎ 登录失败')
		}
	} else {
		login('❌ 未获取到有效URL，请切换url');
	}
}

